<?php $organization = $organization ?? []; $editing = !empty($organization['id']); $h = static fn ($value): string => htmlspecialchars((string) $value, ENT_QUOTES, 'UTF-8'); ?>
<div class="container mx-auto max-w-3xl p-6"><a href="/admin/organizations" class="mb-6 inline-flex rounded-lg bg-gray-200 px-4 py-2 font-semibold text-gray-800 hover:bg-gray-300">Torna alle organizzazioni</a><h1 class="mb-6 text-3xl font-semibold text-gray-800"><?= $editing ? 'Modifica organizzazione' : 'Nuova organizzazione' ?></h1><?php if ($message = \App\Core\Session::getFlash('error')): ?><div class="mb-4 rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-800"><?= $h($message) ?></div><?php endif; ?><form method="POST" action="<?= $editing ? '/admin/organizations/' . (int) $organization['id'] . '/update' : '/admin/organizations/store' ?>" enctype="multipart/form-data" class="space-y-5 rounded-2xl bg-white p-6 shadow-sm ring-1 ring-gray-200"><input type="hidden" name="csrf_token" value="<?= $h($csrf_token) ?>"><div><label for="name" class="block text-sm font-semibold">Nome</label><input id="name" name="name" required maxlength="180" value="<?= $h($organization['name'] ?? '') ?>" class="mt-2 w-full rounded-lg border border-gray-300 px-3 py-2"></div><div><label for="owner_user_id" class="block text-sm font-semibold">Owner</label><select id="owner_user_id" name="owner_user_id" required class="mt-2 w-full rounded-lg border border-gray-300 px-3 py-2"><option value="">Seleziona utente</option><?php foreach ($users as $user): ?><option value="<?= (int) $user['id'] ?>" <?= (int) ($organization['owner_user_id'] ?? 0) === (int) $user['id'] ? 'selected' : '' ?>><?= $h($user['username']) ?> (<?= $h($user['email']) ?>)</option><?php endforeach; ?></select></div><div><label for="email" class="block text-sm font-semibold">Email</label><input id="email" type="email" name="email" maxlength="255" value="<?= $h($organization['email'] ?? '') ?>" class="mt-2 w-full rounded-lg border border-gray-300 px-3 py-2"></div><div><label for="website_url" class="block text-sm font-semibold">Sito web</label><input id="website_url" type="url" name="website_url" maxlength="500" value="<?= $h($organization['website_url'] ?? '') ?>" class="mt-2 w-full rounded-lg border border-gray-300 px-3 py-2"></div><div><label for="organization-logo" class="block text-sm font-semibold">Immagine principale</label><input id="organization-logo" type="file" name="logo" accept="image/jpeg,image/png,image/webp" class="mt-2 w-full rounded-lg border border-gray-300 px-3 py-2"><?php if (!empty($organization['logo_path'])): ?><img src="/public_assets<?= $h($organization['logo_path']) ?>" alt="Immagine principale <?= $h($organization['name']) ?>" class="mt-3 h-24 w-24 rounded-xl border border-gray-200 object-cover"><?php endif; ?></div><div><label for="organization-cover" class="block text-sm font-semibold">Cover</label><input id="organization-cover" type="file" name="cover" accept="image/jpeg,image/png,image/webp" class="mt-2 w-full rounded-lg border border-gray-300 px-3 py-2"><?php if (!empty($organization['cover_path'])): ?><img src="/public_assets<?= $h($organization['cover_path']) ?>" alt="Cover <?= $h($organization['name']) ?>" class="mt-3 h-24 w-full rounded-xl border border-gray-200 object-cover"><?php endif; ?></div><div><label for="description" class="block text-sm font-semibold">Descrizione</label><textarea id="description" name="description" rows="5" class="mt-2 w-full rounded-lg border border-gray-300 px-3 py-2"><?= $h($organization['description'] ?? '') ?></textarea></div><div><label for="status" class="block text-sm font-semibold">Stato</label><select id="status" name="status" class="mt-2 w-full rounded-lg border border-gray-300 px-3 py-2"><?php foreach (['draft', 'pending_review', 'active', 'suspended', 'archived'] as $status): ?><option value="<?= $status ?>" <?= ($organization['status'] ?? 'draft') === $status ? 'selected' : '' ?>><?= $status ?></option><?php endforeach; ?></select></div><label class="flex items-center gap-2 text-sm"><input type="checkbox" name="is_public" value="1" <?= !empty($organization['is_public']) ? 'checked' : '' ?>> Pubblica organizzazione</label><button class="rounded-lg bg-green-800 px-5 py-3 font-semibold text-white hover:bg-green-900">Salva organizzazione</button></form></div>
